# Standalone deterministic verifier. No imports, no I/O, no print.
# Pure function: returns True iff the embedded witness satisfies every gate;
# returns False on any mismatch (fail-closed). Byte-exact equality only.

def verify():
    w = {
        'expected_fields': {'proofs': 'none', 'per_contract': 'none'},
        'abort_table': [
            {'gate': 'certificate_line_1', 'condition': 'missing proved reduction', 'action': 'abort'},
            {'gate': 'certificate_line_2', 'condition': 'missing proved reduction', 'action': 'abort'}
        ],
        'asserted_outcome': 'ABORT',
        'engine': 'CPython3-stdlib-only, byte-exact string equality, no floats, no network, no filesystem, deterministic, fail-closed'
    }
    # Gate 0: exact schema
    if set(w.keys()) != {'expected_fields', 'abort_table', 'asserted_outcome', 'engine'}:
        return False
    # Gate 1: expected fields match the literals exactly
    if w['expected_fields'] != {'proofs': 'none', 'per_contract': 'none'}:
        return False
    # Gate 2: every certificate line aborts as recorded
    if len(w['abort_table']) != 2:
        return False
    for rec in w['abort_table']:
        if set(rec.keys()) != {'gate', 'condition', 'action'}:
            return False
        if rec['action'] != 'abort':
            return False
        if rec['condition'] != 'missing proved reduction':
            return False
    if w['abort_table'][0]['gate'] != 'certificate_line_1':
        return False
    if w['abort_table'][1]['gate'] != 'certificate_line_2':
        return False
    # Gate 3: asserted outcome is the abort, per contract
    if w['asserted_outcome'] != 'ABORT':
        return False
    # Gate 4: engine constraints recorded
    e = w['engine']
    if 'stdlib' not in e or 'fail-closed' not in e or 'no network' not in e or 'no filesystem' not in e:
        return False
    return True

RESULT = verify()  # True == PASS, False == FAIL (fail-closed)
